import json,re,numpy as np
from scipy.optimize import curve_fit
d={x['doc_id']:x['text'] for x in json.load(open('inputs.json'))['documents']}
W={}  # id -> [cond, S_uM, v_uMs]
def add(i,c,S,v): W[i]=[c,S,v]
# D1
blk=d['D1'].split('```')[1]
for ln in blk.strip().splitlines()[1:]:
    f=ln.split(';')
    # condition field contains ';'? no, but has commas
    i=f[0]; S=float(f[-3].replace(',','.')); v=float(f[-2].replace(',','.'))/60
    n=int(i[3:])
    c='C4' if 759<=n<=768 else 'C2' if 494<=n<=503 else 'C5' if 692<=n<=701 else 'C4'
    add(i,c,S,v)
# D2
cur=None
for ln in d['D2'].splitlines():
    if ln.startswith('### Plate'): cur='C5' if 'Plate 9' in ln else 'C1'
    m=re.match(r'\| (OB-\d+) \| \w+ \| ([\d.]+) \| ([\d.]+) \|',ln)
    if m: add(m[1],cur,float(m[2])*1000,float(m[3])/1000)
# D3
cur=None
for ln in d['D3'].splitlines():
    m=re.match(r'Condition: .*?(C\d)',ln)
    if m: cur=m[1]
    m=re.match(r'\s+\[S\] = ([\d.]+):(.*)',ln)
    if m:
        S=float(m[1])
        for part in m[2].split('|'):
            vals=re.findall(r'(?<![\w-])(\d+\.?\d*(?:e\d+)?)',part.split('(')[0])
            i=re.search(r'(OB-\d+)',part)[1]
            add(i,cur,S,float(vals[-1])/60)
# D4, D14
amap={'25C/pH6.5':'C6','20C/pH8.5 +TX-118 5uM':'C7','42C/pH7.4, TX-118 at 0.25 mM':'C8',
 '20 °C, pH 8.5, 0 µM TX-118':'C5','25 °C, pH 8.0':'C4','25 °C, pH 6.5':'C6','37 °C, pH 8.0':'C3'}
for k in ('D4','D14'):
    for ln in d[k].splitlines():
        m=re.match(r'Plate \d+ \| Assay: (.*?) \|',ln)
        if m: cur=amap[m[1]]
        m=re.match(r'\w+\s+(OB-\d+)\s+([\d.]+) (µM|mM|uM)\s+(-[\d.]+)',ln)
        if m: add(m[1],cur,float(m[2])*(1000 if m[3]=='mM' else 1),abs(float(m[4]))/(6.22*0.58*60))
# D11
cm={'Violet block':'C8','Blue block':'C3','Granite block':'C4','Coral block':'C7'}
for ln in d['D11'].split('```')[1].splitlines():
    if ln.startswith('OB-'):
        f=ln.split(','); add(f[0],cm[f[3]],float(f[5])/1000,float(f[6])*1000/60)
W['OB-0580'][1],W['OB-0584'][1]=W['OB-0584'][1],W['OB-0580'][1]
# D13
cur=None
for seg in re.split(r'(?=\d\d:\d\d (?:Set up|Loaded|Started))',d['D13']):
    m=re.search(r'(?:condition|of) (C\d) on plate',seg)
    if not m: continue
    cur=m[1]
    def num(s): 
        s=s.replace('×10^','e'); return float(s)
    for pat in [r'(OB-\d+) \(([\d.×^-]+)\): ([\d.×^-]+)',r'(OB-\d+) at ([\d.×^-]+) gave ([\d.×^-]+)']:
        for a,b,c in re.findall(pat,seg): add(a,cur,num(b)*1000,num(c)*1000/60)
    for b,c,a in re.findall(r'([\d.×^-]+) → ([\d.×^-]+) \((OB-\d+)\)',seg): add(a,cur,num(b)*1000,num(c)*1000/60)
    for a,c,b in re.findall(r'(OB-\d+): ([\d.×^-]+) at ([\d.×^-]+)',seg): add(a,cur,num(b)*1000,num(c)*1000/60)
    for a,b,c in re.findall(r'Well \w+ / (OB-\d+), \[S\] ([\d.×^-]+), v0 ([\d.×^-]+)',seg): add(a,cur,num(b)*1000,num(c)*1000/60)
# D7 raw overrides rates
for ln in d['D7'].splitlines():
    m=re.match(r'\d+\s+\w+\s+(OB-\d+)\s+([\d.]+)',ln)
    if m: W[m[1]][2]=float(m[2])
for i in W:
    if W[i][0]=='C2': W[i][2]/=2
excl=['OB-0760','OB-0700','OB-0802','OB-0625','OB-0681','OB-0513','OB-0816','OB-0744','OB-0541','OB-0640','OB-0665']
from collections import Counter
print(len(W),Counter(v[0] for v in W.values()))
mm=lambda S,V,K:V*S/(K+S)
res={}
def data(c): 
    a=np.array([W[i][1:] for i in W if W[i][0]==c and i not in excl]);return a[:,0],a[:,1]
for c in ['C2','C3','C4','C5','C6']:
    S,v=data(c); p,_=curve_fit(mm,S,v,p0=[v.max(),50]); res[c]=p
    print(c,len(S),p, np.round(v-mm(S,*p),3))
for c,b in [('C1','C5'),('C7','C5'),('C8','C2')]:
    S,v=data(c);V=res[b][0]; p,_=curve_fit(lambda S,K:mm(S,V,K),S,v,p0=[100]); res[c]=[V,p[0]]
    print(c,len(S),res[c],np.round(v-mm(S,V,p[0]),3))
json.dump({"conditions":[{"condition_id":f"C{k}","vmax":float(res[f'C{k}'][0]),"km":float(res[f'C{k}'][1])} for k in range(1,9)],"excluded_samples":excl},open('answer.json','w'),indent=1)

